//! IBL1 R0 + R1 (ruling 117) — the ENVIRONMENT light: a prefiltered octahedral radiance chain
//! sampled by the six lit producers' ambient specular through the existing split sum.
//!
//! # The asset (cut D-P2a; ruling 123 (3))
//!
//! [`STUDIO_ENV_BLOB`] is the procedural studio room baked OFFLINE by
//! `boyko_shaderdsl::ibl::bake_studio_into` (the `bake_ibl_studio` bin) into a 64-byte header and a
//! 256² × 7 bordered octahedral B10G11R11 chain. It is a derived, sync-gated artifact (the `.spv` /
//! SMAA-LUT class): generated by an in-repo deterministic host bake, committed, and pinned by
//! `tests/ibl_studio_sync.rs`, which re-bakes it and compares the bytes. No asset file is loaded,
//! no decoder runs, and nothing is licensed. [`parse_env_blob`] reads the header once, cold, at
//! boot.
//!
//! What this rung keeps and drops is listed in `ibl1/cut.md` §1.2.2: no `.hdr` decoder, no
//! equirect resampling, no `EnvHandle` asset column, no DFG LUT, no SH-9 (the diffuse keeps the
//! hemisphere term with lanes derived from the map), no environment-drawn background.

// ---- The asset ------------------------------------------------------------------------------------

/// The 8-byte magic every baked environment blob opens with (`boyko_shaderdsl::ibl::ENV_BLOB_MAGIC`).
pub const ENV_BLOB_MAGIC: [u8; 8] = *b"BKENVO01";
/// The blob header's size in bytes.
pub const ENV_BLOB_HEADER_BYTES: usize = 64;
/// The chain texel format the blob declares, `VK_FORMAT_B10G11R11_UFLOAT_PACK32`.
pub const ENV_FORMAT_B10G11R11: u32 = 122;
/// The header flag bit that would mark a sun baked into the map. This rung's maps are SUN-LESS
/// (the analytic sun stays the key, so the sun is never counted twice — design D14); a blob with
/// it set is refused.
pub const ENV_FLAG_SUN_BAKED: u32 = 1;
/// The studio blob's byte size (header + the 256² × 7 chain).
pub const STUDIO_ENV_BLOB_BYTES: usize = 349_568;

/// The committed studio environment blob. The array type is its size check: a re-bake that
/// changes the size fails to compile here.
pub static STUDIO_ENV_BLOB: &[u8; STUDIO_ENV_BLOB_BYTES] = include_bytes!("../assets/ibl/studio_256.envoct");

/// A parsed environment blob header (all fields little-endian in the blob).
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct EnvAssetHeader {
    /// Level-0 side in texels (a power of two ≥ 4).
    pub tile: u32,
    /// Level count; level `levels − 1` keeps a side ≥ 4.
    pub levels: u32,
    /// The chain's texel format ([`ENV_FORMAT_B10G11R11`]).
    pub format: u32,
    /// Flag bits ([`ENV_FLAG_SUN_BAKED`] must be clear).
    pub flags: u32,
    /// The upper-hemisphere SKY-row lane `E(+y)/π` at intensity 1 (D20).
    pub sky_lane: [f32; 3],
    /// The lower-hemisphere SKY-row lane `E(−y)/π` at intensity 1.
    pub ground_lane: [f32; 3],
    /// The normalization factor the bake applied (reported; the runtime does not use it).
    pub k: f32,
    /// The chain's byte count.
    pub chain_bytes: u32,
}

/// A parsed environment blob: its header and the level-major chain bytes it describes.
#[derive(Clone, Copy, Debug)]
pub struct EnvAsset<'a> {
    /// The parsed header.
    pub header: EnvAssetHeader,
    /// The chain, level-major and row-major, 4 bytes per texel.
    pub chain: &'a [u8],
}

/// Why [`parse_env_blob`] refused a blob.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum EnvBlobError {
    /// Shorter than the 64-byte header.
    TooShort,
    /// The magic is not `BKENVO01`.
    BadMagic,
    /// A texel format this rung does not sample.
    UnsupportedFormat(u32),
    /// A sun-baked map (this rung's maps are sun-less).
    SunBaked,
    /// The tile / level shape is not a power-of-two chain ending at a side ≥ 4.
    BadShape {
        /// The declared level-0 side.
        tile: u32,
        /// The declared level count.
        levels: u32,
    },
    /// The chain is not the size the shape implies.
    ChainSize {
        /// The size the shape implies.
        want: usize,
        /// The size the blob carries.
        got: usize,
    },
}

/// The byte size of a `levels`-level 4-byte-texel chain of level-0 side `tile`.
#[must_use]
pub const fn env_chain_bytes(tile: u32, levels: u32) -> usize {
    let mut k = 0;
    let mut total = 0usize;
    while k < levels {
        let side = tile >> k;
        total += (side as usize) * (side as usize) * 4;
        k += 1;
    }
    total
}

fn le_u32(b: &[u8], at: usize) -> u32 {
    u32::from_le_bytes([b[at], b[at + 1], b[at + 2], b[at + 3]])
}

fn le_f32(b: &[u8], at: usize) -> f32 {
    f32::from_bits(le_u32(b, at))
}

/// Parses an environment blob (header layout: `boyko_shaderdsl::ibl::write_env_blob`). Cold: run
/// once at boot.
///
/// # Errors
/// [`EnvBlobError`] when the blob is truncated, not an environment blob, sun-baked, in a format
/// this rung does not sample, or not the size its shape implies.
pub fn parse_env_blob(bytes: &[u8]) -> Result<EnvAsset<'_>, EnvBlobError> {
    if bytes.len() < ENV_BLOB_HEADER_BYTES {
        return Err(EnvBlobError::TooShort);
    }
    if bytes[0..8] != ENV_BLOB_MAGIC {
        return Err(EnvBlobError::BadMagic);
    }
    let header = EnvAssetHeader {
        tile: le_u32(bytes, 8),
        levels: le_u32(bytes, 12),
        format: le_u32(bytes, 16),
        flags: le_u32(bytes, 20),
        sky_lane: [le_f32(bytes, 24), le_f32(bytes, 28), le_f32(bytes, 32)],
        ground_lane: [le_f32(bytes, 36), le_f32(bytes, 40), le_f32(bytes, 44)],
        k: le_f32(bytes, 48),
        chain_bytes: le_u32(bytes, 52),
    };
    if header.format != ENV_FORMAT_B10G11R11 {
        return Err(EnvBlobError::UnsupportedFormat(header.format));
    }
    if header.flags & ENV_FLAG_SUN_BAKED != 0 {
        return Err(EnvBlobError::SunBaked);
    }
    // At most 16 levels (the mipped upload's plan capacity); the last level keeps a side ≥ 4.
    let shape_ok = header.tile.is_power_of_two()
        && (1..=16).contains(&header.levels)
        && (header.tile >> (header.levels - 1)) >= 4;
    if !shape_ok {
        return Err(EnvBlobError::BadShape { tile: header.tile, levels: header.levels });
    }
    let want = env_chain_bytes(header.tile, header.levels);
    let got = bytes.len() - ENV_BLOB_HEADER_BYTES;
    if want != got || header.chain_bytes as usize != got {
        return Err(EnvBlobError::ChainSize { want, got });
    }
    Ok(EnvAsset { header, chain: &bytes[ENV_BLOB_HEADER_BYTES..] })
}
